Algorithm Fechas
  Switch dateTimeOf(2026, 11, 7, 18, 30, 0, 0, 3600) Do
    Some(cita):
      Write cita.isoFormat(), " ", cita.weekday();
    None:
      Write "fecha inválida";
  EndSwitch
  Switch dateTimeOf(2026, 2, 30, 0, 0, 0, 0, 0) Do
    Some(otra): Write otra.isoFormat();
    None: Write "el 30 de febrero no existe";
  EndSwitch
  Write dateTimeUtc(0).isoFormat();
EndAlgorithm

Subroutine PausaCorta() As Result<Integer, IoError>
  Define reloj As Clock <- Propagate requestClock();
  Define temporizador As Timer <- Propagate requestTimer();
  Define antes As Integer <- Propagate reloj.now();
  Define despues As Integer <- Propagate temporizador.wait(2000000000);
  Return Success(despues - antes);
EndSubroutine

Algorithm Pausa
  Switch PausaCorta() Do
    Success(nanosegundos): Write nanosegundos / 1000000000;
    Failure(problema): Write problema.code;
  EndSwitch
EndAlgorithm
